const body = $input.item.json.body || {};
const question = (body.question || '').trim();
const userId = body.userId;
if (!userId) throw new Error('Unauthorized: Missing user ID');
if (question.length === 0) throw new Error('Question cannot be empty');
if (question.length > 2000) throw new Error('Question exceeds maximum length of 2000 characters');
return { json: { question, userId } };

const jevResult = $('TypeSafe Jev Request').item.json;
const rule = $('Fetch Routing Rule').item.json || {};
const settings = $('Fetch User Settings').item.json || {};
const question = $('Validate Input').item.json.question;
const userId = $('Validate Input').item.json.userId;
const category = jevResult.category?.value || 'other';
const difficulty = jevResult.difficulty?.value || 3;
const riskObj = jevResult.high_stakes_risk;
const isHighRisk = riskObj?.value === true || riskObj?.probability > 0.5;
const confidence = jevResult.confidence || 0.8;
const threshold = settings.confidence_threshold ?? 0.75;
const preference = settings.preference || 'best_quality';
let recommendedModel = rule.model || 'gpt-4o';
let reason = rule.reason || 'Default routing applied.';
let cheaperAlt = rule.cheaper_alternative;
let strongerAlt = rule.stronger_alternative;
if (isHighRisk) {
  recommendedModel = strongerAlt || 'claude-3-5-sonnet';
  reason = 'High-stakes risk detected (legal/medical/financial). Routed to strongest model. Please verify with a professional.';
} else if (confidence < threshold) {
  recommendedModel = strongerAlt || recommendedModel;
  reason = `Confidence (${confidence}) is below threshold (${threshold}). Upgraded to stronger model for reliability.`;
} else if (preference === 'cheaper' && cheaperAlt) {
  recommendedModel = cheaperAlt;
  reason = `User preference is set to cheaper. Selected economical alternative: ${cheaperAlt}.`;
}
return {
  json: {
    userId,
    category,
    difficulty,
    risk: isHighRisk ? 'High' : 'Low',
    recommended_model: recommendedModel,
    reason,
    confidence,
    cheaper_alternative: cheaperAlt,
    stronger_alternative: strongerAlt,
    question_text: settings.do_not_store_question ? null : question
  }
};
